122	    @Transactional
123	    public ShipmentStatus updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
124	        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
125	                shipmentId, courier, trackingNumber);
126	
127	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
128	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
129	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
130	        }
131	
132	        try {
