134	            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
135	                    .orElseThrow(() -> new ShipmentException(
136	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
137	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
138	                    ));
139	
140	            log.debug("배송 정보 조회 완료: shipmentId={}, 현재상태={}",
