142	
143	            // 2) 송장 정보 업데이트 (택배사, 송장번호)
144	            shipment.updateTrackingInfo(courier, trackingNumber);
145	            log.debug("송장 정보 업데이트 완료: courier={}, trackingNumber={}", courier, trackingNumber);
146	
147	            // 3) CJ대한통운 조회로 현재 상태 확인
148	            String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
149	            ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
150	
151	            log.info("배송 상태 조회 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
152	
153	            // 4) 상태에 따른 처리
154	            if (newStatus == ShipmentStatus.DELIVERED) {
155	                log.info("배송 완료 처리: shipmentId={}", shipmentId);
156	
157	                shipment.updateStatus(ShipmentStatus.DELIVERED);
158	
159	                // 주문 완료 로직
160	                completeOrder(shipment.getOrder().getId());
161	
162	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
