164	                shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
165	
166	            } else {
167	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
168	                shipment.updateStatus(ShipmentStatus.IN_TRANSIT);
169	            }
170	
171	            // 5) 상태 반환
172	            log.info("송장 상태 확인 완료: shipmentId={}, finalStatus={}",
173	                    shipmentId, shipment.getStatus());
174	            return shipment.getStatus();
175	
176	        } catch (ShipmentException e) {
177	            throw e;
178	        } catch (Exception e) {
179	            log.error("송장 상태 확인 중 오류 발생: shipmentId={}, error={}",
180	                    shipmentId, e.getMessage(), e);
181	            throw new ShipmentException(
182	                    ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
183	                    "배송 상태 조회 중 오류 발생: " + e.getMessage(),
184	                    e
185	            );
186	        }
187	    }
188	}

